from collections import deque

def stuck_jobs(n, rules):
    after = [[] for _ in range(n)]
    waits = [0] * n
    for a, b in rules:
        if a != b:
            after[a].append(b)
            waits[b] += 1
    ready = deque(j for j in range(n) if waits[j] == 0)
    ran = set()
    while ready:
        j = ready.popleft()
        ran.add(j)
        for k in after[j]:
            waits[k] -= 1
            if waits[k] == 0:
                ready.append(k)
    return [j for j in range(n) if j not in ran]
